-- COMMAND ----------

-- select the starting elo for each team 

select TeamName, Competition, Season, Elo 
from gold_dev.default.team_base_elo as team_base_elo
join gold_dev.default.dim_teams as teams on team_base_elo.TeamId = teams.TeamId
join gold_dev.default.dim_seasons as seasons on team_base_elo.SeasonId = seasons.SeasonId
join gold_dev.default.dim_competitions as comps on team_base_elo.CompetitionId = comps.CompetitionId

-- COMMAND ----------

WITH season_1516 AS (
    SELECT
        fe.TeamId,
        fe.CompetitionId,
        fe.SeasonId,
        fe.RoundOrder,
        fe.EloBefore,
        fe.EloAfter
    FROM gold_dev.default.fact_elo fe
    WHERE fe.SeasonId = 1
)

SELECT DISTINCT
    t.TeamName,
    c.Competition,
    s.Season,
    FIRST_VALUE(EloBefore) OVER (
        PARTITION BY fe.TeamId, fe.CompetitionId, fe.SeasonId
        ORDER BY RoundOrder ASC
        ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING
    ) AS Starting_Elo,
    LAST_VALUE(EloAfter) OVER (
        PARTITION BY fe.TeamId, fe.CompetitionId, fe.SeasonId
        ORDER BY RoundOrder ASC
        ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING
    ) AS Ending_Elo
FROM season_1516 fe
JOIN gold_dev.default.dim_teams t
    ON fe.TeamId = t.TeamId
JOIN gold_dev.default.dim_seasons s
    ON fe.SeasonId = s.SeasonId
JOIN gold_dev.default.dim_competitions c
    ON fe.CompetitionId = c.CompetitionId
ORDER BY t.TeamName, s.Season;

